insert into public.medicines (id, name, ingredient, form, category, rx, price_uzs, barcode, description, warning, analogs) values
  ('a1000000-0000-4000-8000-000000000001', 'Paracetamol 500 mg', 'paracetamol', 'tablet', 'pain', false, 4500, '4781000000011', '{"uz":"Isitma va o‘rtacha og‘riqni (bosh, tish, mushak) pasaytiradi.","ru":"Снижает температуру и умеренную боль (головную, зубную, мышечную).","en":"Lowers fever and relieves mild to moderate pain (headache, toothache, muscle pain)."}'::jsonb, '{"uz":"Sutkalik dozadan oshirmang (kattalar — 4 g). Jigar kasalligida va spirtli ichimlik bilan birga ichmang.","ru":"Не превышайте суточную дозу (взрослым — 4 г). Нельзя при болезнях печени и вместе с алкоголем.","en":"Do not exceed the daily dose (adults: 4 g). Avoid with liver disease or alcohol."}'::jsonb, array['a1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004']::text[]),
  ('a1000000-0000-4000-8000-000000000002', 'Panadol 500 mg', 'paracetamol', 'tablet', 'pain', false, 28000, '4781000000028', '{"uz":"Isitma va o‘rtacha og‘riqni (bosh, tish, mushak) pasaytiradi.","ru":"Снижает температуру и умеренную боль (головную, зубную, мышечную).","en":"Lowers fever and relieves mild to moderate pain (headache, toothache, muscle pain)."}'::jsonb, '{"uz":"Sutkalik dozadan oshirmang (kattalar — 4 g). Jigar kasalligida va spirtli ichimlik bilan birga ichmang.","ru":"Не превышайте суточную дозу (взрослым — 4 г). Нельзя при болезнях печени и вместе с алкоголем.","en":"Do not exceed the daily dose (adults: 4 g). Avoid with liver disease or alcohol."}'::jsonb, array['a1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004']::text[]),
  ('a1000000-0000-4000-8000-000000000003', 'Efferalgan 500 mg', 'paracetamol', 'tablet', 'pain', false, 39000, '4781000000035', '{"uz":"Isitma va o‘rtacha og‘riqni (bosh, tish, mushak) pasaytiradi.","ru":"Снижает температуру и умеренную боль (головную, зубную, мышечную).","en":"Lowers fever and relieves mild to moderate pain (headache, toothache, muscle pain)."}'::jsonb, '{"uz":"Sutkalik dozadan oshirmang (kattalar — 4 g). Jigar kasalligida va spirtli ichimlik bilan birga ichmang.","ru":"Не превышайте суточную дозу (взрослым — 4 г). Нельзя при болезнях печени и вместе с алкоголем.","en":"Do not exceed the daily dose (adults: 4 g). Avoid with liver disease or alcohol."}'::jsonb, array['a1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004']::text[]),
  ('a1000000-0000-4000-8000-000000000004', 'Paracetamol sirop 120 mg/5 ml', 'paracetamol', 'syrup', 'pain', false, 12000, '4781000000042', '{"uz":"Isitma va o‘rtacha og‘riqni (bosh, tish, mushak) pasaytiradi.","ru":"Снижает температуру и умеренную боль (головную, зубную, мышечную).","en":"Lowers fever and relieves mild to moderate pain (headache, toothache, muscle pain)."}'::jsonb, '{"uz":"Sutkalik dozadan oshirmang (kattalar — 4 g). Jigar kasalligida va spirtli ichimlik bilan birga ichmang.","ru":"Не превышайте суточную дозу (взрослым — 4 г). Нельзя при болезнях печени и вместе с алкоголем.","en":"Do not exceed the daily dose (adults: 4 g). Avoid with liver disease or alcohol."}'::jsonb, array['a1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003']::text[]),
  ('a1000000-0000-4000-8000-000000000005', 'Ibuprofen 400 mg', 'ibuprofen', 'tablet', 'pain', false, 9000, '4781000000059', '{"uz":"Og‘riq, yallig‘lanish va isitmani kamaytiradi.","ru":"Уменьшает боль, воспаление и температуру.","en":"Reduces pain, inflammation and fever."}'::jsonb, '{"uz":"Ovqatdan keyin iching. Oshqozon yarasi, buyrak kasalligi va homiladorlikning oxirgi oylarida mumkin emas.","ru":"Принимать после еды. Нельзя при язве желудка, болезнях почек и в последние месяцы беременности.","en":"Take after food. Not for stomach ulcers, kidney disease or late pregnancy."}'::jsonb, array['a1000000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000007']::text[]),
  ('a1000000-0000-4000-8000-000000000006', 'Nurofen 200 mg', 'ibuprofen', 'tablet', 'pain', false, 35000, '4781000000066', '{"uz":"Og‘riq, yallig‘lanish va isitmani kamaytiradi.","ru":"Уменьшает боль, воспаление и температуру.","en":"Reduces pain, inflammation and fever."}'::jsonb, '{"uz":"Ovqatdan keyin iching. Oshqozon yarasi, buyrak kasalligi va homiladorlikning oxirgi oylarida mumkin emas.","ru":"Принимать после еды. Нельзя при язве желудка, болезнях почек и в последние месяцы беременности.","en":"Take after food. Not for stomach ulcers, kidney disease or late pregnancy."}'::jsonb, array['a1000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000007']::text[]),
  ('a1000000-0000-4000-8000-000000000007', 'Nurofen sirop 100 mg/5 ml', 'ibuprofen', 'syrup', 'pain', false, 48000, '4781000000073', '{"uz":"Og‘riq, yallig‘lanish va isitmani kamaytiradi.","ru":"Уменьшает боль, воспаление и температуру.","en":"Reduces pain, inflammation and fever."}'::jsonb, '{"uz":"Ovqatdan keyin iching. Oshqozon yarasi, buyrak kasalligi va homiladorlikning oxirgi oylarida mumkin emas.","ru":"Принимать после еды. Нельзя при язве желудка, болезнях почек и в последние месяцы беременности.","en":"Take after food. Not for stomach ulcers, kidney disease or late pregnancy."}'::jsonb, array['a1000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000006']::text[]),
  ('a1000000-0000-4000-8000-000000000008', 'Analgin 500 mg', 'metamizole', 'tablet', 'pain', false, 6000, '4781000000080', '{"uz":"Og‘riq qoldiruvchi va isitma tushiruvchi vosita.","ru":"Обезболивающее и жаропонижающее средство.","en":"Pain reliever and fever reducer."}'::jsonb, '{"uz":"Uzoq vaqt ichmang — qon tarkibiga ta’sir qilishi mumkin. Bolalarga faqat shifokor tavsiyasi bilan.","ru":"Не принимать долго — может влиять на состав крови. Детям — только по назначению врача.","en":"Not for long-term use — may affect blood counts. For children only on a doctor’s advice."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000009', 'Sitramon P', 'acetylsalicylic acid + paracetamol + caffeine', 'tablet', 'pain', false, 5000, '4781000000097', '{"uz":"Bosh og‘rig‘i va migrenda yordam beradi.","ru":"Помогает при головной боли и мигрени.","en":"Helps with headache and migraine."}'::jsonb, '{"uz":"15 yoshgacha, oshqozon yarasi va yuqori qon bosimida mumkin emas.","ru":"Нельзя до 15 лет, при язве желудка и высоком давлении.","en":"Not for under 15s, stomach ulcers or high blood pressure."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000010', 'No-shpa 40 mg', 'drotaverine', 'tablet', 'stomach', false, 32000, '4781000000103', '{"uz":"Silliq mushaklar spazmini bo‘shatadi: oshqozon, ichak, siydik yo‘llari og‘rig‘ida.","ru":"Снимает спазм гладких мышц: при болях в желудке, кишечнике, мочевых путях.","en":"Relaxes smooth muscle spasms: stomach, bowel or urinary tract cramps."}'::jsonb, '{"uz":"Kuchli yoki uzoq davom etgan qorin og‘rig‘ida avval shifokorga murojaat qiling.","ru":"При сильной или долгой боли в животе сначала обратитесь к врачу.","en":"For severe or lasting abdominal pain, see a doctor first."}'::jsonb, array['a1000000-0000-4000-8000-000000000011']::text[]),
  ('a1000000-0000-4000-8000-000000000011', 'Drotaverin 40 mg', 'drotaverine', 'tablet', 'stomach', false, 8000, '4781000000110', '{"uz":"Silliq mushaklar spazmini bo‘shatadi: oshqozon, ichak, siydik yo‘llari og‘rig‘ida.","ru":"Снимает спазм гладких мышц: при болях в желудке, кишечнике, мочевых путях.","en":"Relaxes smooth muscle spasms: stomach, bowel or urinary tract cramps."}'::jsonb, '{"uz":"Kuchli yoki uzoq davom etgan qorin og‘rig‘ida avval shifokorga murojaat qiling.","ru":"При сильной или долгой боли в животе сначала обратитесь к врачу.","en":"For severe or lasting abdominal pain, see a doctor first."}'::jsonb, array['a1000000-0000-4000-8000-000000000010']::text[]),
  ('a1000000-0000-4000-8000-000000000012', 'Aspirin Cardio 100 mg', 'acetylsalicylic acid', 'tablet', 'heart', false, 42000, '4781000000127', '{"uz":"Qonni suyultiradi: kichik dozada infarkt va insult profilaktikasi uchun.","ru":"Разжижает кровь: малые дозы для профилактики инфаркта и инсульта.","en":"Low-dose blood thinner to prevent heart attack and stroke."}'::jsonb, '{"uz":"Uzoq muddat faqat shifokor tavsiyasi bilan ichiladi. Qon ketish xavfini oshiradi.","ru":"Длительно — только по назначению врача. Повышает риск кровотечений.","en":"Long-term use only as prescribed. Increases bleeding risk."}'::jsonb, array['a1000000-0000-4000-8000-000000000013']::text[]),
  ('a1000000-0000-4000-8000-000000000013', 'Asekardol 100 mg', 'acetylsalicylic acid', 'tablet', 'heart', false, 14000, '4781000000134', '{"uz":"Qonni suyultiradi: kichik dozada infarkt va insult profilaktikasi uchun.","ru":"Разжижает кровь: малые дозы для профилактики инфаркта и инсульта.","en":"Low-dose blood thinner to prevent heart attack and stroke."}'::jsonb, '{"uz":"Uzoq muddat faqat shifokor tavsiyasi bilan ichiladi. Qon ketish xavfini oshiradi.","ru":"Длительно — только по назначению врача. Повышает риск кровотечений.","en":"Long-term use only as prescribed. Increases bleeding risk."}'::jsonb, array['a1000000-0000-4000-8000-000000000012']::text[]),
  ('a1000000-0000-4000-8000-000000000014', 'Amlodipin 5 mg', 'amlodipine', 'tablet', 'heart', true, 12000, '4781000000141', '{"uz":"Qon bosimini pasaytiradi, stenokardiyada qo‘llaniladi.","ru":"Снижает давление, применяется при стенокардии.","en":"Lowers blood pressure; used for angina."}'::jsonb, '{"uz":"Retsept bo‘yicha. Oyoqlarda shish paydo bo‘lishi mumkin. To‘satdan to‘xtatmang.","ru":"По рецепту. Возможны отёки ног. Не прекращайте приём резко.","en":"Prescription only. May cause ankle swelling. Do not stop suddenly."}'::jsonb, array['a1000000-0000-4000-8000-000000000015']::text[]),
  ('a1000000-0000-4000-8000-000000000015', 'Norvasc 5 mg', 'amlodipine', 'tablet', 'heart', true, 65000, '4781000000158', '{"uz":"Qon bosimini pasaytiradi, stenokardiyada qo‘llaniladi.","ru":"Снижает давление, применяется при стенокардии.","en":"Lowers blood pressure; used for angina."}'::jsonb, '{"uz":"Retsept bo‘yicha. Oyoqlarda shish paydo bo‘lishi mumkin. To‘satdan to‘xtatmang.","ru":"По рецепту. Возможны отёки ног. Не прекращайте приём резко.","en":"Prescription only. May cause ankle swelling. Do not stop suddenly."}'::jsonb, array['a1000000-0000-4000-8000-000000000014']::text[]),
  ('a1000000-0000-4000-8000-000000000016', 'Lizinopril 10 mg', 'lisinopril', 'tablet', 'heart', true, 14000, '4781000000165', '{"uz":"Qon bosimini pasaytiradi va yurakni himoya qiladi (AAF ingibitori).","ru":"Снижает давление и защищает сердце (ингибитор АПФ).","en":"Lowers blood pressure and protects the heart (ACE inhibitor)."}'::jsonb, '{"uz":"Retsept bo‘yicha. Quruq yo‘tal paydo bo‘lishi mumkin. Homiladorlikda mumkin emas.","ru":"По рецепту. Возможен сухой кашель. Нельзя при беременности.","en":"Prescription only. May cause a dry cough. Not for use in pregnancy."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000017', 'Enalapril 10 mg', 'enalapril', 'tablet', 'heart', true, 9000, '4781000000172', '{"uz":"Qon bosimini pasaytiradi va yurakni himoya qiladi (AAF ingibitori).","ru":"Снижает давление и защищает сердце (ингибитор АПФ).","en":"Lowers blood pressure and protects the heart (ACE inhibitor)."}'::jsonb, '{"uz":"Retsept bo‘yicha. Quruq yo‘tal paydo bo‘lishi mumkin. Homiladorlikda mumkin emas.","ru":"По рецепту. Возможен сухой кашель. Нельзя при беременности.","en":"Prescription only. May cause a dry cough. Not for use in pregnancy."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000018', 'Metformin 850 mg', 'metformin', 'tablet', 'diabetes', true, 18000, '4781000000189', '{"uz":"2-tur qandli diabetda qondagi qand miqdorini pasaytiradi.","ru":"Снижает сахар крови при диабете 2 типа.","en":"Lowers blood sugar in type 2 diabetes."}'::jsonb, '{"uz":"Retsept bo‘yicha, ovqat bilan iching. Buyrak yetishmovchiligida mumkin emas.","ru":"По рецепту, во время еды. Нельзя при почечной недостаточности.","en":"Prescription only; take with meals. Not for kidney failure."}'::jsonb, array['a1000000-0000-4000-8000-000000000019']::text[]),
  ('a1000000-0000-4000-8000-000000000019', 'Siofor 850', 'metformin', 'tablet', 'diabetes', true, 45000, '4781000000196', '{"uz":"2-tur qandli diabetda qondagi qand miqdorini pasaytiradi.","ru":"Снижает сахар крови при диабете 2 типа.","en":"Lowers blood sugar in type 2 diabetes."}'::jsonb, '{"uz":"Retsept bo‘yicha, ovqat bilan iching. Buyrak yetishmovchiligida mumkin emas.","ru":"По рецепту, во время еды. Нельзя при почечной недостаточности.","en":"Prescription only; take with meals. Not for kidney failure."}'::jsonb, array['a1000000-0000-4000-8000-000000000018']::text[]),
  ('a1000000-0000-4000-8000-000000000020', 'Amoksitsillin 500 mg', 'amoxicillin', 'capsule', 'antibiotic', true, 22000, '4781000000202', '{"uz":"Bakterial infeksiyalarga qarshi antibiotik (tomoq, quloq, nafas yo‘llari).","ru":"Антибиотик против бактериальных инфекций (горло, уши, дыхательные пути).","en":"Antibiotic for bacterial infections (throat, ear, airways)."}'::jsonb, '{"uz":"Faqat retsept bo‘yicha. Kursni oxirigacha iching. Penitsillinga allergiyada mumkin emas.","ru":"Только по рецепту. Пропейте курс до конца. Нельзя при аллергии на пенициллин.","en":"Prescription only. Finish the full course. Not for penicillin allergy."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000021', 'Amoksiklav 625 mg', 'amoxicillin + clavulanic acid', 'tablet', 'antibiotic', true, 68000, '4781000000219', '{"uz":"Kengaytirilgan ta’sirli antibiotik: amoksitsillin va klavulan kislota.","ru":"Антибиотик расширенного действия: амоксициллин с клавулановой кислотой.","en":"Broad-spectrum antibiotic: amoxicillin with clavulanic acid."}'::jsonb, '{"uz":"Faqat retsept bo‘yicha. Kursni oxirigacha iching. Penitsillinga allergiyada mumkin emas.","ru":"Только по рецепту. Пропейте курс до конца. Нельзя при аллергии на пенициллин.","en":"Prescription only. Finish the full course. Not for penicillin allergy."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000022', 'Azitromitsin 500 mg', 'azithromycin', 'tablet', 'antibiotic', true, 26000, '4781000000226', '{"uz":"Antibiotik, odatda 3 kunlik kurs.","ru":"Антибиотик, обычно курс 3 дня.","en":"Antibiotic, usually a 3-day course."}'::jsonb, '{"uz":"Faqat retsept bo‘yicha. Yurak ritmi buzilishida ehtiyot bo‘ling.","ru":"Только по рецепту. Осторожно при нарушениях ритма сердца.","en":"Prescription only. Use with caution in heart rhythm disorders."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000023', 'Loratadin 10 mg', 'loratadine', 'tablet', 'allergy', false, 7000, '4781000000233', '{"uz":"Allergiyaga qarshi: burun oqishi, aksirish, qichishishda. Uyqu keltirmaydi.","ru":"Против аллергии: насморк, чихание, зуд. Не вызывает сонливости.","en":"Antihistamine for runny nose, sneezing and itching. Non-drowsy."}'::jsonb, '{"uz":"2 yoshgacha bolalarga mumkin emas. Homiladorlikda shifokor bilan maslahatlashing.","ru":"Нельзя детям до 2 лет. При беременности — после консультации врача.","en":"Not for children under 2. Ask a doctor if pregnant."}'::jsonb, array['a1000000-0000-4000-8000-000000000024']::text[]),
  ('a1000000-0000-4000-8000-000000000024', 'Klaritin 10 mg', 'loratadine', 'tablet', 'allergy', false, 52000, '4781000000240', '{"uz":"Allergiyaga qarshi: burun oqishi, aksirish, qichishishda. Uyqu keltirmaydi.","ru":"Против аллергии: насморк, чихание, зуд. Не вызывает сонливости.","en":"Antihistamine for runny nose, sneezing and itching. Non-drowsy."}'::jsonb, '{"uz":"2 yoshgacha bolalarga mumkin emas. Homiladorlikda shifokor bilan maslahatlashing.","ru":"Нельзя детям до 2 лет. При беременности — после консультации врача.","en":"Not for children under 2. Ask a doctor if pregnant."}'::jsonb, array['a1000000-0000-4000-8000-000000000023']::text[]),
  ('a1000000-0000-4000-8000-000000000025', 'Setirizin 10 mg', 'cetirizine', 'tablet', 'allergy', false, 9000, '4781000000257', '{"uz":"Allergiyaga qarshi: burun oqishi, ko‘z yoshlanishi, eshakemda.","ru":"Против аллергии: насморк, слезотечение, крапивница.","en":"Antihistamine for runny nose, watery eyes and hives."}'::jsonb, '{"uz":"Uyquchanlik bo‘lishi mumkin — mashina haydashda ehtiyot bo‘ling.","ru":"Может вызывать сонливость — осторожно за рулём.","en":"May cause drowsiness — take care when driving."}'::jsonb, array['a1000000-0000-4000-8000-000000000026']::text[]),
  ('a1000000-0000-4000-8000-000000000026', 'Zirtek 10 mg', 'cetirizine', 'tablet', 'allergy', false, 61000, '4781000000264', '{"uz":"Allergiyaga qarshi: burun oqishi, ko‘z yoshlanishi, eshakemda.","ru":"Против аллергии: насморк, слезотечение, крапивница.","en":"Antihistamine for runny nose, watery eyes and hives."}'::jsonb, '{"uz":"Uyquchanlik bo‘lishi mumkin — mashina haydashda ehtiyot bo‘ling.","ru":"Может вызывать сонливость — осторожно за рулём.","en":"May cause drowsiness — take care when driving."}'::jsonb, array['a1000000-0000-4000-8000-000000000025']::text[]),
  ('a1000000-0000-4000-8000-000000000027', 'Suprastin 25 mg', 'chloropyramine', 'tablet', 'allergy', false, 29000, '4781000000271', '{"uz":"Tez ta’sir qiluvchi allergiyaga qarshi vosita.","ru":"Быстродействующее противоаллергическое средство.","en":"Fast-acting antihistamine."}'::jsonb, '{"uz":"Uyqu keltiradi. Spirtli ichimlik bilan birga ichmang, mashina haydamang.","ru":"Вызывает сонливость. Не сочетать с алкоголем, не садиться за руль.","en":"Causes drowsiness. Avoid alcohol and driving."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000028', 'Omeprazol 20 mg', 'omeprazole', 'capsule', 'stomach', false, 11000, '4781000000288', '{"uz":"Oshqozon kislotasini kamaytiradi: jig‘ildon qaynashi va gastritda.","ru":"Снижает кислотность желудка: при изжоге и гастрите.","en":"Reduces stomach acid: heartburn and gastritis."}'::jsonb, '{"uz":"Ovqatdan oldin iching. 2 haftadan ortiq — faqat shifokor nazoratida.","ru":"Принимать до еды. Дольше 2 недель — под контролем врача.","en":"Take before meals. Longer than 2 weeks only under a doctor’s care."}'::jsonb, array['a1000000-0000-4000-8000-000000000029']::text[]),
  ('a1000000-0000-4000-8000-000000000029', 'Omez 20 mg', 'omeprazole', 'capsule', 'stomach', false, 24000, '4781000000295', '{"uz":"Oshqozon kislotasini kamaytiradi: jig‘ildon qaynashi va gastritda.","ru":"Снижает кислотность желудка: при изжоге и гастрите.","en":"Reduces stomach acid: heartburn and gastritis."}'::jsonb, '{"uz":"Ovqatdan oldin iching. 2 haftadan ortiq — faqat shifokor nazoratida.","ru":"Принимать до еды. Дольше 2 недель — под контролем врача.","en":"Take before meals. Longer than 2 weeks only under a doctor’s care."}'::jsonb, array['a1000000-0000-4000-8000-000000000028']::text[]),
  ('a1000000-0000-4000-8000-000000000030', 'Smekta 3 g', 'diosmectite', 'powder', 'stomach', false, 36000, '4781000000301', '{"uz":"Ich ketishda toksinlarni bog‘laydi va ichakni himoya qiladi.","ru":"При диарее связывает токсины и защищает кишечник.","en":"Binds toxins and protects the gut in diarrhoea."}'::jsonb, '{"uz":"Boshqa dorilardan 2 soat farq bilan iching. Qonli ich ketishida darhol shifokorga.","ru":"Принимать с интервалом 2 часа от других лекарств. При диарее с кровью — сразу к врачу.","en":"Take 2 hours apart from other medicines. Bloody diarrhoea — see a doctor at once."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000031', 'Mezim forte', 'pancreatin', 'tablet', 'stomach', false, 30000, '4781000000318', '{"uz":"Ovqat hazm qilishga yordam beruvchi fermentlar.","ru":"Ферменты, помогающие пищеварению.","en":"Digestive enzymes that help break down food."}'::jsonb, '{"uz":"Ovqat paytida iching. O‘tkir pankreatitda mumkin emas.","ru":"Принимать во время еды. Нельзя при остром панкреатите.","en":"Take with meals. Not for acute pancreatitis."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000032', 'Regidron', 'oral rehydration salts', 'powder', 'stomach', false, 15000, '4781000000325', '{"uz":"Ich ketishi va qusishda suv-tuz balansini tiklaydi.","ru":"Восстанавливает водно-солевой баланс при диарее и рвоте.","en":"Restores fluids and salts after diarrhoea or vomiting."}'::jsonb, '{"uz":"Ko‘rsatmaga ko‘ra suvda eriting. Bolada suvsizlanish belgilari bo‘lsa — shifokorga.","ru":"Разводите по инструкции. Признаки обезвоживания у ребёнка — к врачу.","en":"Dissolve exactly as directed. Signs of dehydration in a child — see a doctor."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000033', 'Faollashtirilgan ko‘mir 250 mg', 'activated charcoal', 'tablet', 'stomach', false, 3000, '4781000000332', '{"uz":"Zaharlanish va qorin dam bo‘lishida toksinlarni bog‘laydi.","ru":"Связывает токсины при отравлении и вздутии.","en":"Binds toxins in food poisoning and bloating."}'::jsonb, '{"uz":"Boshqa dorilardan 2 soat farq bilan iching. Og‘ir zaharlanishda — 103.","ru":"Принимать через 2 часа после других лекарств. При тяжёлом отравлении — 103.","en":"Take 2 hours apart from other medicines. Severe poisoning — call 103."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000034', 'Ambroksol 30 mg', 'ambroxol', 'tablet', 'cold', false, 8000, '4781000000349', '{"uz":"Balg‘amni suyultiradi va yo‘talda ko‘chishini osonlashtiradi.","ru":"Разжижает мокроту и облегчает её отхождение при кашле.","en":"Thins mucus and makes coughing it up easier."}'::jsonb, '{"uz":"Yo‘talni bosuvchi dorilar bilan birga ichmang. Homiladorlikning 1-uch oyligida mumkin emas.","ru":"Не сочетать с противокашлевыми средствами. Нельзя в первом триместре беременности.","en":"Do not combine with cough suppressants. Not in the first trimester of pregnancy."}'::jsonb, array['a1000000-0000-4000-8000-000000000035']::text[]),
  ('a1000000-0000-4000-8000-000000000035', 'Ambroksol sirop 15 mg/5 ml', 'ambroxol', 'syrup', 'cold', false, 16000, '4781000000356', '{"uz":"Balg‘amni suyultiradi va yo‘talda ko‘chishini osonlashtiradi.","ru":"Разжижает мокроту и облегчает её отхождение при кашле.","en":"Thins mucus and makes coughing it up easier."}'::jsonb, '{"uz":"Yo‘talni bosuvchi dorilar bilan birga ichmang. Homiladorlikning 1-uch oyligida mumkin emas.","ru":"Не сочетать с противокашлевыми средствами. Нельзя в первом триместре беременности.","en":"Do not combine with cough suppressants. Not in the first trimester of pregnancy."}'::jsonb, array['a1000000-0000-4000-8000-000000000034']::text[]),
  ('a1000000-0000-4000-8000-000000000036', 'Ksilometazolin 0.1% sprey', 'xylometazoline', 'spray', 'cold', false, 14000, '4781000000363', '{"uz":"Burun bitishini tez yengillashtiradi.","ru":"Быстро снимает заложенность носа.","en":"Quickly relieves a blocked nose."}'::jsonb, '{"uz":"5–7 kundan ortiq ishlatmang — o‘rganib qolish mumkin.","ru":"Не используйте дольше 5–7 дней — возможно привыкание.","en":"Do not use for more than 5–7 days — may cause dependence."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000037', 'Vitamin D3 2000 ME', 'cholecalciferol', 'capsule', 'vitamins', false, 55000, '4781000000370', '{"uz":"D vitamini: suyaklar va immunitet uchun.","ru":"Витамин D: для костей и иммунитета.","en":"Vitamin D for bones and immunity."}'::jsonb, '{"uz":"Dozani oshirmang. Uzoq muddat ichishdan oldin qondagi darajasini tekshiring.","ru":"Не превышайте дозу. Перед длительным приёмом проверьте уровень в крови.","en":"Do not exceed the dose. Check your blood level before long-term use."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000038', 'Askorbin kislota 50 mg', 'ascorbic acid', 'tablet', 'vitamins', false, 3500, '4781000000387', '{"uz":"C vitamini: immunitetni qo‘llab-quvvatlaydi.","ru":"Витамин C: поддерживает иммунитет.","en":"Vitamin C to support immunity."}'::jsonb, '{"uz":"Buyrakda tosh bo‘lsa, katta dozalarda ichmang.","ru":"При камнях в почках не принимать большие дозы.","en":"Avoid high doses if you have kidney stones."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000039', 'Levomekol malhami', 'chloramphenicol + methyluracil', 'ointment', 'skin', false, 18000, '4781000000394', '{"uz":"Yiringli yara va kuyishlarni davolash uchun malham.","ru":"Мазь для лечения гнойных ран и ожогов.","en":"Ointment for infected wounds and burns."}'::jsonb, '{"uz":"Faqat tashqi qo‘llash uchun. Allergiya bo‘lsa, to‘xtating.","ru":"Только наружно. При аллергии прекратите применение.","en":"For external use only. Stop if an allergy develops."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000040', 'Sulfatsetamid 20% ko‘z tomchisi', 'sulfacetamide', 'drops', 'eye', false, 9000, '4781000000400', '{"uz":"Ko‘zning bakterial yallig‘lanishida (kon’yunktivit) tomchi.","ru":"Капли при бактериальном воспалении глаз (конъюнктивите).","en":"Eye drops for bacterial conjunctivitis."}'::jsonb, '{"uz":"Tomizganda achishishi mumkin. 2–3 kunda yaxshilanmasa — ko‘z shifokoriga.","ru":"Может щипать при закапывании. Нет улучшения за 2–3 дня — к окулисту.","en":"May sting. No improvement in 2–3 days — see an eye doctor."}'::jsonb, '{}'::text[]),
  ('a1000000-0000-4000-8000-000000000041', 'Valeriana 20 mg', 'valerian', 'tablet', 'nerves', false, 6000, '4781000000417', '{"uz":"Yengil tinchlantiruvchi: asabiylik va uyqusizlikda.","ru":"Мягкое успокоительное: при нервозности и бессоннице.","en":"Mild sedative for nervousness and trouble sleeping."}'::jsonb, '{"uz":"Uyquchanlik keltirishi mumkin. Spirtli ichimlik bilan birga ichmang.","ru":"Может вызывать сонливость. Не сочетать с алкоголем.","en":"May cause drowsiness. Avoid alcohol."}'::jsonb, '{}'::text[])
