-- =====================================================================
-- Sino — modul B: medicines, pharmacies, pharmacy_stock va doctors.
-- AVTOMATIK yaratilgan: dart run tool/pharmacy/gen_seed.dart
-- Qo‘lda tahrirlamang — assets/pharmacy/*.json ni o‘zgartiring.
-- =====================================================================

on conflict (id) do update set
  name = excluded.name, ingredient = excluded.ingredient, form = excluded.form, category = excluded.category,
  rx = excluded.rx, price_uzs = excluded.price_uzs, barcode = excluded.barcode, description = excluded.description,
  warning = excluded.warning, analogs = excluded.analogs;

on conflict (id) do update set
  name = excluded.name, address = excluded.address, lat = excluded.lat, lng = excluded.lng,
  hours = excluded.hours, open24 = excluded.open24, rating = excluded.rating;

on conflict (id) do update set
  pharmacy_id = excluded.pharmacy_id, medicine_id = excluded.medicine_id,
  price_uzs = excluded.price_uzs, qty = excluded.qty;

on conflict (id) do update set
  name = excluded.name, specialty = excluded.specialty, years = excluded.years, rating = excluded.rating,
  price_uzs = excluded.price_uzs, clinic = excluded.clinic, online = excluded.online;
